/* Шаги цепочек наставника и пути — на общем движке «Больших дел». */
const МСТ170_ШАГИ=(x,спис,дом)=>{const Ш=x.Ш;const out=[];let от=дом;
 спис.forEach((s,i)=>{const [вид,a,b,c]=s;
  if(вид==="принести")out.push(Ш.принести(дом,null,a,b,["«Вот это дело»."],{дикая:true}));
  else if(вид==="починить"){out.push(Ш.починить(дом,a,b,3,c,["Работа сделана."]));}
  else if(вид==="найти"){const т=x.точка(от,80,400,"н"+i);out.push(Ш.найти(т,a,a,b,[`Найдено: ${a}.`]));от=т;}
  else if(вид==="к_точке"){const т=x.точка(от,120,600,"т"+i);out.push(Ш.к_точке(т,a,b,[`Вы на месте: ${a}.`]));от=т;}
  else if(вид==="убить")out.push(Ш.убить(a,null,b));
  else if(вид==="засада"){const т=x.точка(от,60,300,"з"+i);out.push(Ш.засада(т,"место засады",a,"лихие люди",b,["Засада разбита."]));}
  else if(вид==="ждать")out.push(Ш.ждать(a,b,["Время вышло."]));
  else if(вид==="выбор")out.push(Ш.выбор(a,b.map(l=>({l,итог:"Ответ принят."})),a));});
 return out;};
